40|export async function listUsers(rawQuery: Record<string, unknown> = {}) {
41|  const query = parseUsersListQuery(rawQuery);
42|  const { items: rows, totalCount } = await listUsersFilteredRows(query);
43|
44|  const items = rows.map((row) => ({
45|    ...row,
46|    avatar_url: row.has_profile_image_xs ? buildUserAvatarXsPath(row.id) : null,
47|    locked: Boolean(row.locked),
48|    locked_at: row.locked_at ?? null,
49|    locked_by: row.locked_by ?? null,
50|    locked_by_username: row.locked_by_username ?? null,
51|    unlocked_at: row.unlocked_at ?? null,
52|    unlocked_by: row.unlocked_by ?? null,
53|    unlocked_by_username: row.unlocked_by_username ?? null,
54|    is_builtin: Boolean(row.is_builtin),
55|    roles: row.roles,
56|    role: row.role,
57|  }));
58|
59|  return { body: { success: true as const, items, totalCount } };
