62|export async function createUser(
63|  actor: ActorContext,
64|  payload: Record<string, unknown>,
65|) {
66|  const role = payload.role ?? 'USER';
67|  const roles = payload.roles;
68|  const rawUsername = toOptionalTrimmed(payload.username);
69|  const rawEmail = toOptionalTrimmed(payload.email);
70|  const passwordText = String(payload.password || '');
71|
72|  if (!passwordText) {
73|    throw new HttpError(400, 'password is required.');
74|  }
75|  if (!rawUsername && !rawEmail) {
76|    throw new HttpError(400, 'username or email is required.');
77|  }
78|
79|  const normalizedRoles = normalizeRolesInput(roles, role);
80|  const validation = await validateRoles(normalizedRoles);
81|  if (validation.invalid.length > 0) {
82|    throw new HttpError(400, `Invalid roles: ${validation.invalid.join(', ')}`);
83|  }
84|
85|  const profile = normalizeProfilePayload(payload);
86|  await ensureBaseInfoCode(profile.genderCode, BASE_INFO_ROOT_GENDER, 'genderCode');
87|  await ensureBaseInfoCode(profile.personTypeCode, BASE_INFO_ROOT_PERSON_TYPE, 'personTypeCode');
88|
89|  const resolvedUsername = (rawUsername || rawEmail?.split('@')[0] || '').trim().toLowerCase();
90|  const resolvedEmail = rawEmail || null;
91|  const hash = await hashPassword(passwordText);
92|  const currentActorId = actorId(actor);
93|
94|  await insertUser(resolvedUsername, resolvedEmail, hash, currentActorId);
95|
96|  const insertedUser = await findUserIdByUsername(resolvedUsername);
97|  const userId = Number(insertedUser?.id || 0);
98|  if (!userId) {
99|    throw new Error('Failed to resolve created user id.');
100|  }
101|
102|  await assignUserRoles(userId, normalizedRoles);
103|
104|  if (hasProfilePayloadValue(profile)) {
105|    await upsertUserProfile(userId, profile, currentActorId, { useNullFallbackForImages: true });
106|  }
107|
108|  await touchUsersListEdgeCache();
109|
110|  return { statusCode: 201, body: { success: true as const, id: userId } };
111|}
