113|export async function updateUser(
114|  actor: ActorContext,
115|  userId: number,
116|  payload: Record<string, unknown>,
117|) {
118|  const email = toOptionalTrimmed(payload.email);
119|  const role = payload.role;
120|  const roles = payload.roles;
121|  const passwordText = toOptionalTrimmed(payload.password);
122|
123|  const existing = await findUserIdEmailUsername(userId);
124|  if (!existing) {
125|    throw new HttpError(404, 'User not found.');
126|  }
127|
128|  const existingRoles = await getUserRolesForRequest(userId);
129|  const normalizedRoles = (roles !== undefined || role !== undefined)
130|    ? normalizeRolesInput(roles, role)
131|    : existingRoles;
132|  const validation = await validateRoles(normalizedRoles);
133|  if (validation.invalid.length > 0) {
134|    throw new HttpError(400, `Invalid roles: ${validation.invalid.join(', ')}`);
135|  }
136|
137|  const profile = normalizeProfilePayload(payload);
138|  await ensureBaseInfoCode(profile.genderCode, BASE_INFO_ROOT_GENDER, 'genderCode');
139|  await ensureBaseInfoCode(profile.personTypeCode, BASE_INFO_ROOT_PERSON_TYPE, 'personTypeCode');
140|
141|  const nextEmail = Object.prototype.hasOwnProperty.call(payload, 'email') ? email : existing.email;
142|  const currentActorId = actorId(actor);
143|  await updateUserEmail(nextEmail, currentActorId, userId);
144|
145|  if (roles !== undefined || role !== undefined) {
146|    await assignUserRoles(userId, normalizedRoles);
147|  }
148|
149|  if (passwordText) {
150|    await updateUserPasswordHash(await hashPassword(passwordText), userId);
151|  }
152|
153|  await upsertUserProfile(userId, profile, currentActorId, { useNullFallbackForImages: true });
154|
155|  await touchUsersListEdgeCache();
156|
157|  return { body: { success: true as const } };
158|}
