160|export async function deleteUserRecord(userId: number) {
161|  const existing = await findUserIdBuiltin(userId);
162|  if (!existing) {
163|    throw new HttpError(404, 'User not found.');
164|  }
165|  if (existing.is_builtin) {
166|    throw new HttpError(400, 'Built-in users cannot be deleted.');
167|  }
168|
169|  await deleteUserProfile(userId);
170|  await deleteUser(userId);
171|
172|  await touchUsersListEdgeCache();
173|
174|  return { body: { success: true as const } };
